def test_a_blank_currency_is_rejected(currency: str) -> None:
    with pytest.raises(ValueError, match="currency"):
        Money(Decimal("1"), currency)


def test_money_is_immutable() -> None:
    money = Money(Decimal("1"), "EUR")
    with pytest.raises(FrozenInstanceError):
        money.amount = Decimal("2")  # type: ignore[misc]


def test_the_receipt_describes_amount_currency_and_outcome() -> None:
    from payment.application.authorize_payment import AuthorizePayment
    from payment.domain.authorization_outcome import AuthorizationOutcome

    saved: dict[str, str] = {}

    class Gateway:
        def authorize(self, reference: str, amount: Money) -> AuthorizationOutcome:
            return AuthorizationOutcome.DECLINED

    class Store:
        def save(self, reference: str, body: str) -> None:
            saved[reference] = body

    AuthorizePayment(Gateway(), Store()).handle("R", Money(Decimal("5"), "eur"))
    assert saved == {"R": "EUR 5 -> DECLINED"}
